mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.INTERFACE_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.FROM_APP_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.TO_APP_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.TO_EXTERNAL_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.INTERFACE_ID = #{interfaceId}
AND T1.FROM_APP_ID = #{fromAppId}
AND T1.TO_APP_ID = #{toAppId}
AND T1.PROTOCOL_CD = #{protocolCd}
AND T1.DIRECTION_CD = #{directionCd}
AND T1.CRITICAL_YN = #{criticalYn}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.INTERFACE_ID AS INTERFACE_ID, T1.FROM_APP_ID AS FROM_APP_ID, T1.TO_APP_ID AS TO_APP_ID,
           T1.TO_EXTERNAL_NAME AS TO_EXTERNAL_NAME, T1.PROTOCOL_CD AS PROTOCOL_CD, T1.DIRECTION_CD AS DIRECTION_CD,
           T1.CRITICAL_YN AS CRITICAL_YN, T1.REMARK AS REMARK,
           T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM, T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_APP_INTERFACE_PILOT T1

     ORDER BY T1.CRITICAL_YN DESC, T1.INTERFACE_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.insert:
INSERT INTO TB_IF_APP_INTERFACE_PILOT (
  INTERFACE_ID, FROM_APP_ID, TO_APP_ID, TO_EXTERNAL_NAME, PROTOCOL_CD, DIRECTION_CD,
  CRITICAL_YN, REMARK, REG_USER_ID, REG_DTM
) VALUES (
  #{interfaceId}, #{fromAppId}, #{toAppId}, #{toExternalName}, #{protocolCd}, #{directionCd},
  #{criticalYn}, #{remark}, #{regUserId}, #{regDtm}
)

mapper.update:
UPDATE TB_IF_APP_INTERFACE_PILOT SET
  FROM_APP_ID=#{fromAppId}, TO_APP_ID=#{toAppId}, TO_EXTERNAL_NAME=#{toExternalName},
  PROTOCOL_CD=#{protocolCd}, DIRECTION_CD=#{directionCd}, CRITICAL_YN=#{criticalYn},
  REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE INTERFACE_ID=#{interfaceId}
